"""Self-contained aggregate-only business report, with ratio-safe filters and CSV export."""
import json,html
from pathlib import Path

def make_report(root,kind):
 s=json.loads((root/'evidence/summary.json').read_text());payload=json.dumps(s,allow_nan=False).replace('</','<\\/');fan=kind=='fan'
 title='Fan and Ticketing Intelligence' if fan else 'Survey and Sponsorship Intelligence'
 intro='A fictional two-brand ticketing operation: reconciled revenue, audience actions and next-90-day segment validation.' if fan else 'A fictional survey program and sponsor portfolio: response-bias diagnostics, a randomized recall experiment and delivery recap.'
 main='''<section><div class="section-head"><div><span class="eyebrow">TICKETING OPERATIONS</span><h2>Revenue you can reconcile</h2></div><div class="filters"><label>Brand<select id="brand"></select></label><label>Purchase month<select id="month"></select></label><button onclick="downloadRows()">Export filtered CSV</button></div></div><div id="kpis" class="kpis"></div><div class="two"><article><h3>Net revenue by purchase month</h3><div id="chart"></div></article><article><h3>Ticket mix</h3><div id="mix"></div></article></div><p class="note">Net revenue = paid gross minus refunds, in original transaction month. Attendance / net tickets is a descriptive scan rate, not a causal demand estimate.</p></section><section><span class="eyebrow">AUDIENCE ACTIONS · AS OF JAN 1, 2026</span><h2>Segments with a future check</h2><p>Rules use only earlier purchases. The next 90 days are held out from segment construction. These global segments are separate from the revenue filters above.</p><div id="segments"></div><h3>Product-specific activation counts</h3><div id="products"></div><p class="note">A fan can belong to both brand universes. Counts across brands are not unique people. Individual activation exports require synthetic marketing opt-in and stay outside Git.</p></section>''' if fan else '''<section><span class="eyebrow">SURVEY RESEARCH · DELIVERED INVITATION FRAME</span><h2>Who responded changes the story</h2><div id="surveyKpis" class="kpis"></div><div id="surveyGroups"></div><p class="note">Post-stratification uses known invitation-frame membership counts and assumes response is ignorable within each group. It does not remove unobserved within-group bias. The 95% interval uses 500 within-stratum bootstrap replicates.</p></section><section><span class="eyebrow">PRE-SPECIFIED RANDOMIZED EXPERIMENT</span><h2>Placement and unaided sponsor recall</h2><div id="experimentKpis" class="kpis"></div><div id="experimentChart"></div><p class="note">Randomized inside the simulated survey among complete respondents. Analyze assigned arms; no post-treatment missingness. The endpoint and comparison were fixed in advance. This is simulated experimental evidence, not a real sponsor result.</p></section><section><div class="section-head"><div><span class="eyebrow">PARTNERSHIP RECAP</span><h2>Contract delivery and activation</h2></div><div class="filters"><label>Brand<select id="brand"></select></label><label>Sponsor<select id="sponsor"></select></label><label>Month<select id="month"></select></label><button onclick="downloadRows()">Export filtered CSV</button></div></div><div id="kpis" class="kpis"></div><div id="chart"></div><p class="note">Fulfillment is delivered / planned units and may exceed 100% for overdelivery. Click and redemption rates use their own denominators. Allocated fees and counted impressions are not causal ROI or unique fan reach.</p></section>'''
 script='''const s=DATA;const $=id=>document.getElementById(id);const num=x=>Number(x).toLocaleString(undefined,{maximumFractionDigits:1});const money=x=>'$'+num(x/100);const pct=x=>num(x*100)+'%';const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const sum=(a,k)=>a.reduce((n,r)=>n+Number(r[k]),0);const card=(label,value,detail='')=>`<article class="card"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(detail)}</small></article>`;function table(rows,cols){return '<div class="table-wrap"><table><thead><tr>'+cols.map(c=>'<th>'+esc(c[0])+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+cols.map(c=>'<td>'+esc(c[2]?c[2](r[c[1]],r):r[c[1]])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}function bars(rows,label,value,formatter=num){let max=Math.max(...rows.map(r=>r[value]),1);return rows.map(r=>`<div class="bar-row"><span>${esc(r[label])}</span><div class="track"><i style="width:${Math.max(1,100*r[value]/max)}%"></i></div><b>${esc(formatter(r[value]))}</b></div>`).join('')}function options(id,values){$(id).innerHTML=['All',...new Set(values)].map(v=>`<option>${esc(v)}</option>`).join('');$(id).onchange=render}let filtered=[];function downloadRows(){if(!filtered.length)return;let keys=Object.keys(filtered[0]);let quote=x=>'"'+String(x).replaceAll('"','""')+'"';let csv=keys.map(quote).join(',')+'\\n'+filtered.map(r=>keys.map(k=>quote(r[k])).join(',')).join('\\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='synthetic-filtered-aggregate.csv';a.click();URL.revokeObjectURL(a.href)}'''
 if fan:
  script+='''options('brand',s.monthly.map(r=>r.brand));options('month',s.monthly.map(r=>r.month));function render(){filtered=s.monthly.filter(r=>($('brand').value==='All'||r.brand===$('brand').value)&&($('month').value==='All'||r.month===$('month').value));let rev=sum(filtered,'net_revenue_cents'),tickets=sum(filtered,'net_tickets'),att=sum(filtered,'attended_tickets'),orders=sum(filtered,'orders');$('kpis').innerHTML=card('Net revenue',money(rev))+card('Net tickets',num(tickets))+card('Orders',num(orders))+card('Scanned / net tickets',tickets?pct(att/tickets):'N/A');let months={};let mix={};for(let r of filtered){months[r.month]=(months[r.month]||0)+r.net_revenue_cents;mix[r.ticket_type]=(mix[r.ticket_type]||0)+r.net_tickets}$('chart').innerHTML=bars(Object.entries(months).map(([month,value])=>({month,value})),'month','value',money);$('mix').innerHTML=bars(Object.entries(mix).map(([type,value])=>({type,value})),'type','value');}render();$('segments').innerHTML=table(s.segments,[['Segment','segment'],['Fans','fans',num],['90-day repeat rate','repeat_rate',pct],['95% Wilson interval','ci_low',(x,r)=>pct(x)+' - '+pct(r.ci_high)],['Opted-in fans','opted_in_fans',num]]);$('products').innerHTML=table(s.product_segments,[['Brand','brand'],['Segment','segment'],['Fans','fans',num],['Baseline net spend','baseline_net_cents',money]]);'''
 else:
  script+='''let v=s.survey,e=s.experiment;$('surveyKpis').innerHTML=card('Delivered invites',num(v.delivered_invites))+card('Complete responses',num(v.respondents),pct(v.response_rate)+' response rate')+card('Unweighted NPS',num(v.unweighted_nps),'NPS points, -100 to +100')+card('Post-stratified NPS',num(v.poststratified_nps),num(v.weighted_ci_low)+' to '+num(v.weighted_ci_high)+' · 95% interval');$('surveyGroups').innerHTML=table(v.groups,[['Membership group','group'],['Invited','invited',num],['Responses','respondents',num],['Response rate','response_rate',pct],['NPS','nps',num],['Post-strat weight','poststrat_weight',num]]);$('experimentKpis').innerHTML=card('Neutral recall',pct(e.control_rate),num(e.control_n)+' randomized')+card('Featured recall',pct(e.treatment_rate),num(e.treatment_n)+' randomized')+card('Difference',num(e.difference_pp)+' pp','Primary endpoint')+card('95% score interval',num(e.ci_low_pp)+' to '+num(e.ci_high_pp)+' pp','Two-sided pooled z p='+e.two_sided_p.toExponential(2));$('experimentChart').innerHTML=bars([{arm:'Neutral placement',rate:e.control_rate},{arm:'Featured placement',rate:e.treatment_rate}],'arm','rate',pct);options('brand',s.recap.map(r=>r.brand));options('sponsor',s.recap.map(r=>r.sponsor));options('month',s.recap.map(r=>r.month));function render(){filtered=s.recap.filter(r=>['brand','sponsor','month'].every(k=>$(k).value==='All'||r[k]===$(k).value));let p=sum(filtered,'planned_units'),d=sum(filtered,'delivered_units'),o=sum(filtered,'on_time_units'),i=sum(filtered,'impressions'),c=sum(filtered,'clicks');$('kpis').innerHTML=card('Delivered / planned',num(d)+' / '+num(p),p?pct(d/p)+' fulfillment':'N/A')+card('On-time / delivered',d?pct(o/d):'N/A')+card('Clicks / impressions',i?pct(c/i):'N/A')+card('Allocated fees',money(sum(filtered,'allocated_fee_cents')),'Synthetic contract allocation');$('chart').innerHTML=table(filtered,[['Month','month'],['Brand','brand'],['Sponsor','sponsor'],['Planned','planned_units',num],['Delivered','delivered_units',num],['Clicks','clicks',num],['Redemptions','redemptions',num]]);}render();'''
 audit=json.dumps(s['audit'],indent=2);checks=json.dumps(s['checks'],indent=2);bench=''
 if fan:
  b=json.loads((root/'evidence/sql_benchmark.json').read_text());bench='<h3>SQL query benchmark</h3><p>One-thread DuckDB, warm cache, exact matching results, 21 interleaved runs. Materialized marts require rebuilding after source refresh.</p><table><tr><th>Case</th><th>Baseline p50</th><th>Mart p50</th><th>Speedup</th><th>Build break-even</th></tr>'+''.join(f"<tr><td>{r['case']}</td><td>{r['baseline_p50_ms']:.3f} ms</td><td>{r['optimized_p50_ms']:.3f} ms</td><td>{r['speedup']:.2f}x</td><td>{r['break_even_queries']} queries</td></tr>" for r in b['cases'])+'</table>'
 package='fan_ticketing.twbx' if fan else 'survey_sponsorship.twbx'
 text='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TITLE</title><style>:root{--ink:#152735;--muted:#526775;--gold:#d2a646;--teal:#147d78}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:#f2f4f2;font:15px system-ui,sans-serif}header{background:#102c40;color:white;padding:44px max(5vw,24px)}header h1{font-size:clamp(32px,4vw,56px);max-width:1000px;line-height:1.05;margin:12px 0 20px}header p{max-width:850px;line-height:1.6;color:#d7e1e5}.badge{display:inline-block;border:1px solid #e3c170;border-radius:30px;padding:7px 12px;color:#ffe3a0;font-size:12px;font-weight:700;letter-spacing:1px}nav{display:flex;gap:20px;flex-wrap:wrap;margin-top:26px}nav a{color:#fff;text-decoration:underline}main{max-width:1280px;margin:auto;padding:20px}section{padding:30px 0;border-bottom:1px solid #ccd5da}h2{font-size:30px;margin:8px 0 20px}h3{margin-top:0}.eyebrow{font-size:12px;letter-spacing:1.3px;font-weight:700;color:var(--teal)}.section-head{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap}label{font-size:12px;color:var(--muted)}select,button{display:block;padding:10px;border:1px solid #aebec8;border-radius:6px;background:white;color:var(--ink);margin-top:4px}button{cursor:pointer;background:#153e52;color:white;font-weight:600}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:22px 0}.card,article{background:white;border:1px solid #d6dee0;border-radius:10px;padding:20px;min-width:0}.card span,.card small{display:block;color:var(--muted)}.card strong{display:block;font-size:29px;margin:10px 0;font-variant-numeric:tabular-nums}.card small{font-size:11px;min-height:15px}.two{display:grid;grid-template-columns:1.35fr 1fr;gap:20px}.bar-row{display:grid;grid-template-columns:120px 1fr 90px;gap:10px;align-items:center;margin:13px 0;font-size:12px}.bar-row b{text-align:right}.track{height:16px;background:#edf1ef;border-radius:3px;overflow:hidden}.track i{display:block;height:100%;background:var(--teal)}.note{font-size:12px;line-height:1.6;color:var(--muted);max-width:1000px}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;background:white;font-size:13px}td,th{padding:12px;text-align:left;border-bottom:1px solid #d8e1e2}th{background:#e5eceb;position:sticky;top:0}pre{font-size:12px;background:#e8edeb;padding:16px;white-space:pre-wrap;border-radius:8px}details{margin:15px 0}footer{padding:30px 0;color:var(--muted);font-size:12px}a{color:#076d71}@media(max-width:800px){.kpis{grid-template-columns:repeat(2,1fr)}.two{grid-template-columns:1fr}.bar-row{grid-template-columns:95px 1fr 75px}h2{font-size:25px}}@media(max-width:440px){.kpis{grid-template-columns:1fr}}</style></head><body><header><span class="badge">SYNTHETIC DATA · FICTIONAL BRANDS · NO REAL TEAM RESULTS</span><h1>TITLE</h1><p>INTRO</p><nav><a href="../tableau/PACKAGE">Open Tableau package</a><a href="../evidence/summary.json">Aggregate evidence</a><a href="../docs/analysis_plan.md">Analysis protocol</a><a href="../docs/README_CN.md">中文说明</a></nav></header><main>MAIN<section><span class="eyebrow">QUALITY AND REPRODUCIBILITY</span><h2>Trace the result</h2>BENCH<details><summary>Ingestion and quarantine audit</summary><pre>AUDIT</pre></details><details><summary>Independent numerical checks</summary><pre>CHECKS</pre></details><p>Published charts use aggregate tables only. All names, customer IDs, transactions, survey responses and sponsor deliveries were simulated. Nothing here demonstrates real commercial uplift, real survey fieldwork or external model validity.</p></section><footer>Prepared by Xiangyi (Sam) Kong · Reproduce with bash run_all.sh · Metric definitions and assumptions are versioned in docs/.</footer></main><script>const DATA=PAYLOAD;SCRIPT</script></body></html>'''
 for key,value in [('TITLE',title),('INTRO',intro),('PACKAGE',package),('MAIN',main),('BENCH',bench),('AUDIT',html.escape(audit)),('CHECKS',html.escape(checks)),('PAYLOAD',payload),('SCRIPT',script)]:text=text.replace(key,value)
 (root/'reports/index.html').write_text(text)
